INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/fiverr-studiosquad','studiosquad — Website, E-commerce & Technical Support Collection','portfolio','published','{"body": "This collection brings together 14 completed Fiverr orders associated with the public username studiosquad. Completion dates span April 2020 to February 2025. The records cover multiple website and support requests; the order count is not a count of unique products.\n\nThe documented delivery scope includes a real-estate website with property-listing, agent, blog, contact and enquiry pages. Some listing and agent content was supplied as placeholders pending client information. Other orders cover e-commerce functionality and analytics, website and email recovery, mail-service migration, hosting upgrades and renewals, plugin/theme maintenance and backup handovers. Selected deliveries reference Elementor-compatible editing and optimization-tool setup.", "mode": "enhance", "role": "Freelance website developer and technical support provider", "sources": [], "category": "Freelance Client Projects", "featured": false, "features": ["Real-estate website interfaces with listing, agent, blog and enquiry pages", "E-commerce functionality and analytics integration", "Website and email recovery and mail-service migration", "Hosting renewals/upgrades, plugin/theme updates and backup handovers", "Elementor-compatible page editing and optimization-tool setup"], "description": "Fourteen completed Fiverr orders covering website delivery, e-commerce integration, hosting maintenance and email operations.", "technologies": ["Elementor", "WP-Optimize Pro"], "client_display": "studiosquad", "project_status": "14 historical completed Fiverr orders · current live availability not audited", "evidence_attested": true, "period": "April 2020–February 2025 · completed-order dates"}'::jsonb,'{"body": "This collection brings together 14 completed Fiverr orders associated with the public username studiosquad. Completion dates span April 2020 to February 2025. The records cover multiple website and support requests; the order count is not a count of unique products.\n\nThe documented delivery scope includes a real-estate website with property-listing, agent, blog, contact and enquiry pages. Some listing and agent content was supplied as placeholders pending client information. Other orders cover e-commerce functionality and analytics, website and email recovery, mail-service migration, hosting upgrades and renewals, plugin/theme maintenance and backup handovers. Selected deliveries reference Elementor-compatible editing and optimization-tool setup.", "mode": "enhance", "role": "Freelance website developer and technical support provider", "sources": [], "category": "Freelance Client Projects", "featured": false, "features": ["Real-estate website interfaces with listing, agent, blog and enquiry pages", "E-commerce functionality and analytics integration", "Website and email recovery and mail-service migration", "Hosting renewals/upgrades, plugin/theme updates and backup handovers", "Elementor-compatible page editing and optimization-tool setup"], "description": "Fourteen completed Fiverr orders covering website delivery, e-commerce integration, hosting maintenance and email operations.", "technologies": ["Elementor", "WP-Optimize Pro"], "client_display": "studiosquad", "project_status": "14 historical completed Fiverr orders · current live availability not audited", "evidence_attested": true, "period": "April 2020–February 2025 · completed-order dates"}'::jsonb,'{"title": "studiosquad — Website, E-commerce & Technical Support Collection | Anil Bishnoi", "description": "Fourteen completed Fiverr orders covering website delivery, e-commerce integration, hosting maintenance and email operations.", "canonical": "https://anibish.com/portfolio/fiverr-studiosquad"}'::jsonb,'{"title": "studiosquad — Website, E-commerce & Technical Support Collection | Anil Bishnoi", "description": "Fourteen completed Fiverr orders covering website delivery, e-commerce integration, hosting maintenance and email operations.", "canonical": "https://anibish.com/portfolio/fiverr-studiosquad"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/fiverr-mariakelley','mariakelley — Website Engineering & Maintenance Collection','portfolio','published','{"body": "This collection brings together 14 completed Fiverr orders associated with the public username mariakelley, with completion dates from May 2020 through December 2024. The records cover repeated service deliveries over time; the count does not establish 14 unique websites or one continuous project.\n\nThe documented delivery scope includes responsive website builds and revisions, domain and hosting support, website restoration, plugin configuration, and backup or visual-asset handover. Some orders reference booking or commerce components and guidance for maintaining the delivered website. These capabilities describe the collection as a whole, rather than the scope of every order.", "mode": "enhance", "role": "Freelance website engineering and delivery support", "sources": [], "category": "Freelance Client Projects", "featured": false, "features": ["Responsive website construction and revisions referenced in delivery notes", "Domain/hosting renewal, activation and website-restoration support", "Website plugin, booking or commerce component configuration", "Backup, visual-asset and maintenance-guide handovers"], "description": "A collection of 14 completed Fiverr orders covering documented website delivery, configuration and ongoing maintenance work.", "technologies": ["SSL"], "client_display": "mariakelley", "project_status": "Historical completed-order collection · current live availability not audited", "evidence_attested": true, "period": "May 2020 – December 2024 · displayed completed-order dates"}'::jsonb,'{"body": "This collection brings together 14 completed Fiverr orders associated with the public username mariakelley, with completion dates from May 2020 through December 2024. The records cover repeated service deliveries over time; the count does not establish 14 unique websites or one continuous project.\n\nThe documented delivery scope includes responsive website builds and revisions, domain and hosting support, website restoration, plugin configuration, and backup or visual-asset handover. Some orders reference booking or commerce components and guidance for maintaining the delivered website. These capabilities describe the collection as a whole, rather than the scope of every order.", "mode": "enhance", "role": "Freelance website engineering and delivery support", "sources": [], "category": "Freelance Client Projects", "featured": false, "features": ["Responsive website construction and revisions referenced in delivery notes", "Domain/hosting renewal, activation and website-restoration support", "Website plugin, booking or commerce component configuration", "Backup, visual-asset and maintenance-guide handovers"], "description": "A collection of 14 completed Fiverr orders covering documented website delivery, configuration and ongoing maintenance work.", "technologies": ["SSL"], "client_display": "mariakelley", "project_status": "Historical completed-order collection · current live availability not audited", "evidence_attested": true, "period": "May 2020 – December 2024 · displayed completed-order dates"}'::jsonb,'{"title": "mariakelley — Historical Website Delivery Collection | Anil Bishnoi", "description": "Documented website engineering and maintenance deliveries across 14 completed Fiverr orders. Historical scope; private evidence protected.", "canonical": "https://anibish.com/portfolio/fiverr-mariakelley"}'::jsonb,'{"title": "mariakelley — Historical Website Delivery Collection | Anil Bishnoi", "description": "Documented website engineering and maintenance deliveries across 14 completed Fiverr orders. Historical scope; private evidence protected.", "canonical": "https://anibish.com/portfolio/fiverr-mariakelley"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/fiverr-fandmspices','fandmspices — Website & E-commerce Delivery Collection','portfolio','published','{"body": "Seven completed Fiverr orders associated with the public username fandmspices are grouped in this delivery collection. Their completion dates span July 2022 to October 2024. They are order records across an ongoing body of work, rather than seven independently verified products.\n\nThe documented work began with a custom business website, video-background presentation and Elementor-compatible page editing. Subsequent delivery records describe storefront and customer-account functionality, order and address views, cart/checkout flows, discounts, configurable tax and shipping settings, and payment-option integration. Further orders cover CSS and media refinements, traffic analytics, on-page SEO, social links, hosting renewals and a website backup handover. No current merchant configuration, sales result or live-site availability is asserted.", "mode": "enhance", "role": "Freelance website developer and technical support provider", "sources": [], "category": "Freelance Client Projects", "featured": false, "features": ["Custom website design with video-background presentation and Elementor-compatible editing", "Customer accounts, order/address views and storefront/cart/checkout workflows", "Discount, tax and variable shipping configuration", "Historic payment-option integration", "CSS/media refinements, traffic analytics, on-page SEO and social-link setup", "Hosting renewals and website backup handover"], "description": "Seven completed Fiverr orders covering a custom business website, an online storefront, page refinements and ongoing hosting support.", "technologies": ["Elementor", "CSS", "Google Site Kit"], "client_display": "fandmspices", "project_status": "7 historical completed Fiverr orders · current live availability not audited", "evidence_attested": true, "period": "July 2022–October 2024 · completed-order dates"}'::jsonb,'{"body": "Seven completed Fiverr orders associated with the public username fandmspices are grouped in this delivery collection. Their completion dates span July 2022 to October 2024. They are order records across an ongoing body of work, rather than seven independently verified products.\n\nThe documented work began with a custom business website, video-background presentation and Elementor-compatible page editing. Subsequent delivery records describe storefront and customer-account functionality, order and address views, cart/checkout flows, discounts, configurable tax and shipping settings, and payment-option integration. Further orders cover CSS and media refinements, traffic analytics, on-page SEO, social links, hosting renewals and a website backup handover. No current merchant configuration, sales result or live-site availability is asserted.", "mode": "enhance", "role": "Freelance website developer and technical support provider", "sources": [], "category": "Freelance Client Projects", "featured": false, "features": ["Custom website design with video-background presentation and Elementor-compatible editing", "Customer accounts, order/address views and storefront/cart/checkout workflows", "Discount, tax and variable shipping configuration", "Historic payment-option integration", "CSS/media refinements, traffic analytics, on-page SEO and social-link setup", "Hosting renewals and website backup handover"], "description": "Seven completed Fiverr orders covering a custom business website, an online storefront, page refinements and ongoing hosting support.", "technologies": ["Elementor", "CSS", "Google Site Kit"], "client_display": "fandmspices", "project_status": "7 historical completed Fiverr orders · current live availability not audited", "evidence_attested": true, "period": "July 2022–October 2024 · completed-order dates"}'::jsonb,'{"title": "fandmspices — Website & E-commerce Delivery Collection | Anil Bishnoi", "description": "Seven completed Fiverr orders covering a custom business website, an online storefront, page refinements and ongoing hosting support.", "canonical": "https://anibish.com/portfolio/fiverr-fandmspices"}'::jsonb,'{"title": "fandmspices — Website & E-commerce Delivery Collection | Anil Bishnoi", "description": "Seven completed Fiverr orders covering a custom business website, an online storefront, page refinements and ongoing hosting support.", "canonical": "https://anibish.com/portfolio/fiverr-fandmspices"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
